// Common IR helpers shared by the YAML parser and dumper.

export function isFloat(v) {
  return v !== null && typeof v === 'object' && v.__tag === 'float';
}

export function isTimestamp(v) {
  return v !== null && typeof v === 'object' && v.__tag === 'timestamp';
}

export function makeFloat(n) {
  return { __tag: 'float', value: n };
}

export function makeTimestamp(text) {
  return { __tag: 'timestamp', text };
}

// Equality for mapping keys, following Python dict semantics:
// null == null; booleans/Numbers/BigInts compare by numeric value across
// types (true == 1, false == 0); strings strict-equal; tagged float/timestamp
// objects equal when value/text match (NaN equals NaN as a key); arrays and
// YamlMaps compare only by identity.
export function keyEquals(a, b) {
  if (a === b) return true;

  const isNum = (v) =>
    typeof v === 'number' || typeof v === 'bigint' || typeof v === 'boolean';

  if (isNum(a) && isNum(b)) {
    if (typeof a === 'bigint' || typeof b === 'bigint') {
      // Compare BigInt and Number safely: convert Number to BigInt only when
      // integral; a non-integral Number can never equal a BigInt.
      const toBig = (v) => {
        if (typeof v === 'bigint') return v;
        if (typeof v === 'boolean') return v ? 1n : 0n;
        if (typeof v === 'number' && Number.isInteger(v)) return BigInt(v);
        return null;
      };
      const ba = toBig(a);
      const bb = toBig(b);
      if (ba === null || bb === null) return false;
      return ba === bb;
    }
    return Number(a) === Number(b);
  }

  if (isFloat(a) && isFloat(b)) {
    // Same Number bits; NaN equals NaN for key purposes.
    if (Number.isNaN(a.value) && Number.isNaN(b.value)) return true;
    return Object.is(a.value, b.value) || a.value === b.value;
  }

  if (isTimestamp(a) && isTimestamp(b)) {
    return a.text === b.text;
  }

  return false;
}

export class YamlMap {
  constructor() {
    this.entries = [];
  }

  _findIndex(key) {
    for (let i = 0; i < this.entries.length; i++) {
      if (keyEquals(this.entries[i][0], key)) return i;
    }
    return -1;
  }

  set(key, value) {
    const i = this._findIndex(key);
    if (i >= 0) {
      // Replace in place, keeping the original position (Python dict).
      this.entries[i][1] = value;
    } else {
      this.entries.push([key, value]);
    }
  }

  get(key) {
    const i = this._findIndex(key);
    return i >= 0 ? this.entries[i][1] : undefined;
  }

  has(key) {
    return this._findIndex(key) >= 0;
  }

  get size() {
    return this.entries.length;
  }
}

