// PyYAML-compatible scalar resolution (YAML 1.1 implicit typing) and
// Python repr(float) reproduction for the dumper.

import { makeFloat, makeTimestamp } from './yaml_common.mjs';

const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);

function bigintToIR(v) {
  if (v <= MAX_SAFE && v >= -MAX_SAFE) return Number(v);
  return v;
}

// ---------------------------------------------------------------------------
// null / bool
// ---------------------------------------------------------------------------

const NULL_RE = /^(?:~|null|Null|NULL|)$/;

const BOOL_TRUE = new Set(['yes', 'Yes', 'YES', 'true', 'True', 'TRUE', 'on', 'On', 'ON']);
const BOOL_FALSE = new Set(['no', 'No', 'NO', 'false', 'False', 'FALSE', 'off', 'Off', 'OFF']);

// ---------------------------------------------------------------------------
// int
// ---------------------------------------------------------------------------

const INT_BIN_RE = /^([-+]?)0b([0-1]+)$/;
const INT_OCT_RE = /^([-+]?)(0[0-7]+)$/;
const INT_HEX_RE = /^([-+]?)0x([0-9a-fA-F]+)$/;
const INT_DEC_RE = /^[-+]?(0|[1-9][0-9]*)$/;
const INT_SEX_RE = /^([-+]?)([1-9][0-9]*(?::[0-5]?[0-9])+)$/;

function parseSexagesimalInt(digits) {
  // digits: "1:20:30" (no sign, no underscores)
  let v = 0n;
  for (const part of digits.split(':')) {
    v = v * 60n + BigInt(part);
  }
  return v;
}

// Resolve a plain scalar as int; returns undefined when no int form matches.
function resolveInt(text) {
  // PyYAML strips underscores before parsing.
  const t = text.replace(/_/g, '');
  let m;

  if ((m = INT_BIN_RE.exec(t))) {
    const v = BigInt('0b' + m[2]);
    return bigintToIR(m[1] === '-' ? -v : v);
  }
  if ((m = INT_HEX_RE.exec(t))) {
    const v = BigInt('0x' + m[2]);
    return bigintToIR(m[1] === '-' ? -v : v);
  }
  if ((m = INT_OCT_RE.exec(t))) {
    let v = 0n;
    for (const c of m[2]) v = v * 8n + BigInt(c);
    return bigintToIR(m[1] === '-' ? -v : v);
  }
  if ((m = INT_SEX_RE.exec(t))) {
    const v = parseSexagesimalInt(m[2]);
    return bigintToIR(m[1] === '-' ? -v : v);
  }
  if (INT_DEC_RE.test(t)) {
    return bigintToIR(BigInt(t));
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// float
// ---------------------------------------------------------------------------

const FLOAT_RE = /^[-+]?[0-9][0-9]*\.[0-9]*(?:[eE][-+][0-9]+)?$/;
const FLOAT_DOT_RE = /^\.[0-9][0-9]*(?:[eE][-+][0-9]+)?$/;
const FLOAT_SEX_RE = /^([-+]?)([0-9][0-9]*(?::[0-5]?[0-9])+\.[0-9]*)$/;
const FLOAT_INF_RE = /^([-+]?)\.(?:inf|Inf|INF)$/;
const FLOAT_NAN_RE = /^\.(?:nan|NaN|NAN)$/;

function parseSexagesimalFloat(digits) {
  // digits: "1:30.5" (no sign, no underscores)
  let v = 0;
  for (const part of digits.split(':')) {
    v = v * 60 + Number(part);
  }
  return v;
}

// Resolve a plain scalar as float; returns undefined when no float form matches.
function resolveFloat(text) {
  const t = text.replace(/_/g, '');
  let m;

  if ((m = FLOAT_SEX_RE.exec(t))) {
    const v = parseSexagesimalFloat(m[2]);
    return makeFloat(m[1] === '-' ? -v : v);
  }
  if (FLOAT_RE.test(t) || FLOAT_DOT_RE.test(t)) {
    return makeFloat(Number(t));
  }
  if ((m = FLOAT_INF_RE.exec(t))) {
    return makeFloat(m[1] === '-' ? -Infinity : Infinity);
  }
  if (FLOAT_NAN_RE.test(t)) {
    return makeFloat(NaN);
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// timestamp
// ---------------------------------------------------------------------------

const DATE_RE = /^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})$/;
const DATETIME_RE = /^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})(?:[Tt]|[ \t]+)([0-9]{1,2}):([0-9]{2}):([0-9]{2})(?:\.([0-9]*))?(?:[ \t]*(Z|[-+][0-9]{1,2}(?::[0-9]{2})?))?$/;

function isLeapYear(y) {
  return y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0);
}

function validateDate(y, mo, d) {
  if (y < 1) throw new Error(`year ${y} is out of range`);
  if (mo < 1 || mo > 12) throw new Error('month must be in 1..12');
  const dim = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
  if (d < 1 || d > dim) throw new Error('day is out of range for month');
}

function validateTime(h, mi, s) {
  if (h > 23) throw new Error('hour must be in 0..23');
  if (mi > 59) throw new Error('minute must be in 0..59');
  if (s > 59) throw new Error('second must be in 0..59');
}

const pad2 = (n) => String(n).padStart(2, '0');

// Resolve a plain scalar as timestamp; returns undefined when the text does
// not match either timestamp regex, and throws when it matches but the
// date/time is invalid (mirrors Python's constructor ValueError).
function resolveTimestamp(text) {
  let m = DATE_RE.exec(text);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    validateDate(y, mo, d);
    return makeTimestamp(`${m[1]}-${pad2(mo)}-${pad2(d)}`);
  }

  m = DATETIME_RE.exec(text);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    const h = Number(m[4]);
    const mi = Number(m[5]);
    const s = Number(m[6]);
    const frac = m[7];
    const tz = m[8];
    validateDate(y, mo, d);
    validateTime(h, mi, s);

    let out = `${m[1]}-${pad2(mo)}-${pad2(d)} ${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
    if (frac) {
      // Microseconds: right-pad/truncate to 6 digits.
      out += '.' + (frac + '000000').slice(0, 6);
    }
    if (tz !== undefined) {
      if (tz === 'Z') {
        out += '+00:00';
      } else {
        const sign = tz[0];
        const body = tz.slice(1);
        let hh;
        let mm;
        const ci = body.indexOf(':');
        if (ci >= 0) {
          hh = body.slice(0, ci);
          mm = body.slice(ci + 1);
        } else {
          hh = body;
          mm = '00';
        }
        out += sign + pad2(Number(hh)) + ':' + pad2(Number(mm));
      }
    }
    return makeTimestamp(out);
  }

  return undefined;
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

// PyYAML SafeLoader implicit resolution for a plain scalar.
export function resolvePlainScalar(text) {
  if (NULL_RE.test(text)) return null;
  if (BOOL_TRUE.has(text)) return true;
  if (BOOL_FALSE.has(text)) return false;

  const i = resolveInt(text);
  if (i !== undefined) return i;

  const f = resolveFloat(text);
  if (f !== undefined) return f;

  const ts = resolveTimestamp(text);
  if (ts !== undefined) return ts;

  return text;
}

// Python repr(float).lower() with PyYAML's representer fixup.
export function reprFloat(n) {
  if (Number.isNaN(n)) return '.nan';
  if (n === Infinity) return '.inf';
  if (n === -Infinity) return '-.inf';

  let sign = '';
  if (n < 0 || Object.is(n, -0)) {
    sign = '-';
    n = -n;
  }

  // Shortest round-trip digits and decimal exponent:
  // value = digits[0].digits[1..] x 10^exp
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(n.toExponential());
  const digits = m[1] + (m[2] || '');
  const exp = Number(m[3]);

  let out;
  if (exp >= -4 && exp < 16) {
    // Fixed notation with the decimal point after position exp+1.
    if (exp >= 0) {
      if (exp + 1 >= digits.length) {
        out = digits + '0'.repeat(exp + 1 - digits.length) + '.0';
      } else {
        out = digits.slice(0, exp + 1) + '.' + digits.slice(exp + 1);
      }
    } else {
      out = '0.' + '0'.repeat(-exp - 1) + digits;
    }
  } else {
    // Scientific notation: d[.ddd]e±XX (exponent padded to >= 2 digits).
    const mant = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const eSign = exp < 0 ? '-' : '+';
    const eAbs = String(Math.abs(exp)).padStart(2, '0');
    out = `${mant}e${eSign}${eAbs}`;
  }

  // PyYAML fixup: ensure a '.' is present so the scalar re-resolves as float.
  if (!out.includes('.') && out.includes('e')) {
    out = out.replace('e', '.0e');
  }
  return sign + out;
}

// ---------------------------------------------------------------------------
// explicit tags
// ---------------------------------------------------------------------------

function constructBool(text) {
  const lower = text.toLowerCase();
  if (lower === 'yes' || lower === 'true' || lower === 'on') return true;
  if (lower === 'no' || lower === 'false' || lower === 'off') return false;
  throw new Error(`invalid boolean value: '${text}'`);
}

// Mirrors PyYAML SafeConstructor.construct_yaml_int.
function constructInt(text) {
  let value = text.replace(/_/g, '');
  let neg = false;
  if (value[0] === '-') {
    neg = true;
    value = value.slice(1);
  } else if (value[0] === '+') {
    value = value.slice(1);
  }

  let v;
  if (value.startsWith('0b')) {
    if (!/^[0-1]+$/.test(value.slice(2))) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  } else if (value.startsWith('0x')) {
    if (!/^[0-9a-fA-F]+$/.test(value.slice(2))) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  } else if (value[0] === '0' && value.length > 1) {
    // Python: int(value, 8)
    if (!/^[0-7]+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = 0n;
    for (const c of value) v = v * 8n + BigInt(c);
  } else if (value.includes(':')) {
    if (!/^[0-9]+(:[0-5]?[0-9])+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = parseSexagesimalInt(value);
  } else {
    if (!/^[0-9]+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  }
  return bigintToIR(neg ? -v : v);
}

// Mirrors PyYAML SafeConstructor.construct_yaml_float.
function constructFloat(text) {
  const stripped = text.replace(/_/g, '');
  let lower = stripped.toLowerCase();
  let neg = false;
  if (lower[0] === '-') {
    neg = true;
    lower = lower.slice(1);
  } else if (lower[0] === '+') {
    lower = lower.slice(1);
  }

  if (lower === '.inf' || lower === 'inf' || lower === 'infinity') {
    return makeFloat(neg ? -Infinity : Infinity);
  }
  if (lower === '.nan' || lower === 'nan') {
    return makeFloat(NaN);
  }
  if (lower.includes(':')) {
    const body = neg ? lower : lower; // sign already stripped from lower
    if (!/^[0-9][0-9]*(:[0-5]?[0-9])+\.[0-9]*$/.test(body)) {
      throw new Error(`invalid float value: '${text}'`);
    }
    const v = parseSexagesimalFloat(body);
    return makeFloat(neg ? -v : v);
  }
  const num = Number(stripped);
  if (Number.isNaN(num)) throw new Error(`invalid float value: '${text}'`);
  return makeFloat(num);
}

// Resolve a scalar carrying an explicit tag (e.g. `!!str foo`).
export function resolveTaggedScalar(tag, text) {
  let t = tag;
  if (t.startsWith('!!')) t = 'tag:yaml.org,2002:' + t.slice(2);

  switch (t) {
    case 'tag:yaml.org,2002:str':
      return String(text);
    case 'tag:yaml.org,2002:null':
      // PyYAML constructs null regardless of the scalar text.
      return null;
    case 'tag:yaml.org,2002:bool':
      return constructBool(text);
    case 'tag:yaml.org,2002:int':
      return constructInt(text);
    case 'tag:yaml.org,2002:float':
      return constructFloat(text);
    case 'tag:yaml.org,2002:timestamp': {
      const ts = resolveTimestamp(text);
      if (ts === undefined) {
        throw new Error(`invalid timestamp value: '${text}'`);
      }
      return ts;
    }
    default:
      throw new Error(`could not determine a constructor for the tag '${tag}'`);
  }
}

