  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    validateDate(y, mo, d);
    return makeTimestamp(`${m[1]}-${pad2(mo)}-${pad2(d)}`);
  }

  m = DATETIME_RE.exec(text);
  if (m) {
    const y = Number(m[1]);
    const mo = Number(m[2]);
    const d = Number(m[3]);
    const h = Number(m[4]);
    const mi = Number(m[5]);
    const s = Number(m[6]);
    const frac = m[7];
    const tz = m[8];
    validateDate(y, mo, d);
    validateTime(h, mi, s);

    let out = `${m[1]}-${pad2(mo)}-${pad2(d)} ${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
    if (frac) {
      // Microseconds: right-pad/truncate to 6 digits.
      out += '.' + (frac + '000000').slice(0, 6);
    }
    if (tz !== undefined) {
      if (tz === 'Z') {
        out += '+00:00';
      } else {
        const sign = tz[0];
        const body = tz.slice(1);
        let hh;
        let mm;
        const ci = body.indexOf(':');
        if (ci >= 0) {
          hh = body.slice(0, ci);
          mm = body.slice(ci + 1);
        } else {
          hh = body;
          mm = '00';
        }
        out += sign + pad2(Number(hh)) + ':' + pad2(Number(mm));
      }
    }
    return makeTimestamp(out);
  }

  return undefined;
}

// ---------------------------------------------------------------------------
// public API
// ---------------------------------------------------------------------------

// PyYAML SafeLoader implicit resolution for a plain scalar.
export function resolvePlainScalar(text) {
  if (NULL_RE.test(text)) return null;
  if (BOOL_TRUE.has(text)) return true;
  if (BOOL_FALSE.has(text)) return false;

  const i = resolveInt(text);
  if (i !== undefined) return i;

  const f = resolveFloat(text);
  if (f !== undefined) return f;

  const ts = resolveTimestamp(text);
  if (ts !== undefined) return ts;

  return text;
}

// Python repr(float).lower() with PyYAML's representer fixup.
export function reprFloat(n) {
  if (Number.isNaN(n)) return '.nan';
  if (n === Infinity) return '.inf';
  if (n === -Infinity) return '-.inf';

  let sign = '';
  if (n < 0 || Object.is(n, -0)) {
    sign = '-';
    n = -n;
  }

  // Shortest round-trip digits and decimal exponent:
  // value = digits[0].digits[1..] x 10^exp
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(n.toExponential());
  const digits = m[1] + (m[2] || '');
  const exp = Number(m[3]);

  let out;
  if (exp >= -4 && exp < 16) {
    // Fixed notation with the decimal point after position exp+1.
    if (exp >= 0) {
      if (exp + 1 >= digits.length) {
        out = digits + '0'.repeat(exp + 1 - digits.length) + '.0';
      } else {
        out = digits.slice(0, exp + 1) + '.' + digits.slice(exp + 1);
      }
    } else {
      out = '0.' + '0'.repeat(-exp - 1) + digits;
    }
  } else {
    // Scientific notation: d[.ddd]e±XX (exponent padded to >= 2 digits).
    const mant = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
    const eSign = exp < 0 ? '-' : '+';
    const eAbs = String(Math.abs(exp)).padStart(2, '0');
    out = `${mant}e${eSign}${eAbs}`;
  }

  // PyYAML fixup: ensure a '.' is present so the scalar re-resolves as float.
  if (!out.includes('.') && out.includes('e')) {
    out = out.replace('e', '.0e');
  }
  return sign + out;
}

// ---------------------------------------------------------------------------
// explicit tags
// ---------------------------------------------------------------------------

function constructBool(text) {
  const lower = text.toLowerCase();
  if (lower === 'yes' || lower === 'true' || lower === 'on') return true;
  if (lower === 'no' || lower === 'false' || lower === 'off') return false;
  throw new Error(`invalid boolean value: '${text}'`);
}

// Mirrors PyYAML SafeConstructor.construct_yaml_int.
function constructInt(text) {
  let value = text.replace(/_/g, '');
  let neg = false;
  if (value[0] === '-') {
    neg = true;
    value = value.slice(1);
  } else if (value[0] === '+') {
    value = value.slice(1);
  }

  let v;
  if (value.startsWith('0b')) {
    if (!/^[0-1]+$/.test(value.slice(2))) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  } else if (value.startsWith('0x')) {
    if (!/^[0-9a-fA-F]+$/.test(value.slice(2))) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  } else if (value[0] === '0' && value.length > 1) {
    // Python: int(value, 8)
    if (!/^[0-7]+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = 0n;
    for (const c of value) v = v * 8n + BigInt(c);
  } else if (value.includes(':')) {
    if (!/^[0-9]+(:[0-5]?[0-9])+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = parseSexagesimalInt(value);
  } else {
    if (!/^[0-9]+$/.test(value)) throw new Error(`invalid int value: '${text}'`);
    v = BigInt(value);
  }
  return bigintToIR(neg ? -v : v);
}

// Mirrors PyYAML SafeConstructor.construct_yaml_float.
function constructFloat(text) {
  const stripped = text.replace(/_/g, '');
  let lower = stripped.toLowerCase();
  let neg = false;
  if (lower[0] === '-') {
    neg = true;
    lower = lower.slice(1);
  } else if (lower[0] === '+') {
    lower = lower.slice(1);
  }

  if (lower === '.inf' || lower === 'inf' || lower === 'infinity') {
    return makeFloat(neg ? -Infinity : Infinity);
  }
  if (lower === '.nan' || lower === 'nan') {
    return makeFloat(NaN);
  }
  if (lower.includes(':')) {
    const body = neg ? lower : lower; // sign already stripped from lower
    if (!/^[0-9][0-9]*(:[0-5]?[0-9])+\.[0-9]*$/.test(body)) {
      throw new Error(`invalid float value: '${text}'`);
    }
    const v = parseSexagesimalFloat(body);
    return makeFloat(neg ? -v : v);
  }
  const num = Number(stripped);
  if (Number.isNaN(num)) throw new Error(`invalid float value: '${text}'`);
  return makeFloat(num);
}

// Resolve a scalar carrying an explicit tag (e.g. `!!str foo`).
export function resolveTaggedScalar(tag, text) {
  let t = tag;
  if (t.startsWith('!!')) t = 'tag:yaml.org,2002:' + t.slice(2);

  switch (t) {
    case 'tag:yaml.org,2002:str':
      return String(text);
    case 'tag:yaml.org,2002:null':
      // PyYAML constructs null regardless of the scalar text.
      return null;
    case 'tag:yaml.org,2002:bool':
      return constructBool(text);
    case 'tag:yaml.org,2002:int':
      return constructInt(text);
    case 'tag:yaml.org,2002:float':
      return constructFloat(text);
    case 'tag:yaml.org,2002:timestamp': {
      const ts = resolveTimestamp(text);
      if (ts === undefined) {
        throw new Error(`invalid timestamp value: '${text}'`);
      }
      return ts;
    }
    default:
      throw new Error(`could not determine a constructor for the tag '${tag}'`);
  }
}

