// Minimal reimplementation of the Python argparse parser used by
// test20_executable: one required string option --a, plus -h/--help.

const PROG = 'test20_executable';
const USAGE = `usage: ${PROG} [-h] --a A`;
const HELP =
  USAGE +
  '\n\noptions:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

// argparse's _negative_number_matcher: tokens like "-45" or "-3.14" are
// treated as values rather than options.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function error(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs(argv) {
  let a;
  let aSeen = false;
  const extras = [];
  let positionalOnly = false;

  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];

    if (positionalOnly) {
      extras.push(tok);
      continue;
    }
    if (tok === '--') {
      positionalOnly = true;
      continue;
    }
    if (tok === '-h' || tok === '--help') {
      process.stdout.write(HELP);
      process.exit(0);
    }
    if (tok === '--a') {
      const next = argv[i + 1];
      if (
        next === undefined ||
        (next.startsWith('-') && next !== '-' && !NEGATIVE_NUMBER_RE.test(next))
      ) {
        error('argument --a: expected one argument');
      }
      a = next;
      aSeen = true;
      i++;
      continue;
    }
    if (tok.startsWith('--a=')) {
      a = tok.slice('--a='.length);
      aSeen = true;
      continue;
    }
    extras.push(tok);
  }

  if (extras.length > 0) {
    error('unrecognized arguments: ' + extras.join(' '));
  }
  if (!aSeen) {
    error('the following arguments are required: --a');
  }
  return { a };
}

