cd /output/lib && node -e "
import('./yaml_scalar.mjs').then(({resolvePlainScalar: r, reprFloat, resolveTaggedScalar}) => {
  const eq = (got, want, label) => {
    const g = JSON.stringify(got), w = JSON.stringify(want);
    if (g !== w) { console.log('FAIL', label, 'got', g, 'want', w); process.exitCode = 1; }
  };
  // null / bool
  eq(r(''), null, 'null empty'); eq(r('~'), null, 'null ~'); eq(r('NULL'), null, 'NULL');
  eq(r('yes'), true, 'yes'); eq(r('Off'), false, 'Off'); eq(r('y'), 'y', 'y is string'); eq(r('n'), 'n', 'n is string');
  // int
  eq(r('010'), 8, 'octal 010'); eq(r('007'), 7, 'octal 007'); eq(r('08'), '08', '08 string');
  eq(r('0b101'), 5, 'bin'); eq(r('0x1F'), 31, 'hex'); eq(r('-0x10'), -16, 'hex neg');
  eq(r('1_000'), 1000, 'underscores'); eq(r('1:30'), 90, 'sexagesimal'); eq(r('-2:00'), -120, 'sex neg');
  eq(r('0'), 0, 'zero'); eq(r('+42'), 42, 'plus'); eq(r('9007199254740991'), 9007199254740991, 'maxsafe');
  const big = r('9007199254740993');
  if (typeof big !== 'bigint' || big !== 9007199254740993n) { console.log('FAIL bigint', big); process.exitCode = 1; }
  // float
  eq(r('1.5e+7'), {__tag:'float', value: 15000000}, 'float exp');
  eq(r('1.5e7'), '1.5e7', 'exp without sign is string');
  eq(r('1e3'), '1e3', '1e3 string');
  eq(r('.5'), {__tag:'float', value: 0.5}, '.5');
  eq(r('1:30.5'), {__tag:'float', value: 90.5}, 'sex float');
  eq(r('.inf'), {__tag:'float', value: Infinity}, 'inf');
  eq(r('-.Inf'), {__tag:'float', value: -Infinity}, '-inf');
  const nan = r('.NaN'); if (nan.__tag !== 'float' || !Number.isNaN(nan.value)) { console.log('FAIL nan'); process.exitCode = 1; }
  // timestamp
  eq(r('2020-01-15'), {__tag:'timestamp', text:'2020-01-15'}, 'date');
  eq(r('2020-1-5'), {__tag:'timestamp', text:'2020-01-05'}, 'date pad');
  eq(r('2020-01-15 10:30:00+05:30'), {__tag:'timestamp', text:'2020-01-15 10:30:00+05:30'}, 'dt tz');
  eq(r('2020-01-15T10:30:00Z'), {__tag:'timestamp', text:'2020-01-15 10:30:00+00:00'}, 'dt Z');
  eq(r('2020-01-15 10:30:00.5'), {__tag:'timestamp', text:'2020-01-15 10:30:00.500000'}, 'frac');
  eq(r('2020-01-15 10:30:00+5'), {__tag:'timestamp', text:'2020-01-15 10:30:00+05:00'}, 'tz +5');
  eq(r('2020-01-15 10:30:00-8'), {__tag:'timestamp', text:'2020-01-15 10:30:00-08:00'}, 'tz -8');
  try { r('2020-02-30'); console.log('FAIL invalid date accepted'); process.exitCode = 1; } catch {}
  try { r('2020-01-15 25:00:00'); console.log('FAIL invalid hour accepted'); process.exitCode = 1; } catch {}
  // reprFloat
  eq(reprFloat(1e-5), '1.0e-05', 'repr 1e-5');
  eq(reprFloat(1e16), '1.0e+16', 'repr 1e16');
  eq(reprFloat(1.5e-7), '1.5e-07', 'repr 1.5e-7');
  eq(reprFloat(0.0001), '0.0001', 'repr 1e-4');
  eq(reprFloat(1e15), '1000000000000000.0', 'repr 1e15');
  eq(reprFloat(1000000.0), '1000000.0', 'repr 1e6');
  eq(reprFloat(-0.0), '-0.0', 'repr -0.0');
  eq(reprFloat(NaN), '.nan', 'repr nan');
  eq(reprFloat(Infinity), '.inf', 'repr inf');
  eq(reprFloat(-Infinity), '-.inf', 'repr -inf');
  eq(reprFloat(1e100), '1.0e+100', 'repr 1e100');
  eq(reprFloat(1.7976931348623157e308), '1.7976931348623157e+308', 'repr max');
  eq(reprFloat(0.5), '0.5', 'repr 0.5');
  eq(reprFloat(-2.5), '-2.5', 'repr -2.5');
  eq(reprFloat(1/3), '0.3333333333333333', 'repr 1/3');
  // tagged
  eq(resolveTaggedScalar('!!str', '010'), '010', 'tag str');
  eq(resolveTaggedScalar('!!int', '0x10'), 16, 'tag int hex');
  eq(resolveTaggedScalar('!!float', '1e3'), {__tag:'float', value: 1000}, 'tag float 1e3');
  eq(resolveTaggedScalar('!!bool', 'OFF'), false, 'tag bool');
  eq(resolveTaggedScalar('!!null', 'whatever'), null, 'tag null');
  eq(resolveTaggedScalar('tag:yaml.org,2002:timestamp', '2020-01-15'), {__tag:'timestamp', text:'2020-01-15'}, 'tag ts');
  try { resolveTaggedScalar('!!int', 'abc'); console.log('FAIL tag int abc'); process.exitCode = 1; } catch {}
  try { resolveTaggedScalar('!!unknown', 'x'); console.log('FAIL unknown tag'); process.exitCode = 1; } catch {}
  console.log('scalar tests done');
});
"

